CREATE VIEW grocery_clean.product_pairs_review AS
 SELECT c.product_id_a,
    c.product_id_b,
    c.rules_version,
    c.category,
    c.store_a,
    c.store_b,
    c.name_a,
    c.name_b,
    c.similarity,
    c.auto_label,
    c.reason,
    c.features_a,
    c.features_b,
    c.needs_review,
    c.created_at,
    h.human_label,
    h.comment AS human_comment,
    h.reviewed_at,
        CASE
            WHEN ((h.name_a = c.name_a) AND (h.name_b = c.name_b)) THEN h.human_label
            ELSE NULL::text
        END AS confirmed_label,
    ((h.human_label IS NOT NULL) AND ((h.name_a <> c.name_a) OR (h.name_b <> c.name_b))) AS annotation_stale
   FROM (grocery_clean.product_pair_candidates c
     LEFT JOIN grocery_clean.product_pair_annotations h ON (((h.product_id_a = c.product_id_a) AND (h.product_id_b = c.product_id_b))));


